//! ClaudeCodeConfig entrypoint — hand-owned.
//! Once generated by the ggen lsp-max pack (main.rs.tera); diverged from
//! template output (hand-written verb dispatch, receipt-verify shim, runtime
//! notes), so the generation rule was retired 2026-11-03 (SA-9, GGM-SRC-002
//! honest demotion).

pub mod nouns;

// NOTE: `main` is intentionally NOT `#[tokio::main]`. The `clap-noun-verb`
// dispatch is synchronous and the `serve` verb drives the async LSP server on
// its own runtime; if `main` established an ambient runtime, that verb's
// `block_on` would panic with "Cannot start a runtime from within a runtime".
fn main() -> clap_noun_verb::Result<()> {
    // An LSP client (Claude Code, editors) spawns the binary with no arguments
    // and speaks JSON-RPC over stdio. Default that bare invocation to the
    // server so it works regardless of how it's launched; explicit verbs
    // (`serve --stdio`, `scan`, `--help`, …) still route through the framework.
    if std::env::args().nth(1).is_none() {
        let rt = tokio::runtime::Runtime::new().expect("failed to build tokio runtime");
        rt.block_on(nouns::config::start_stdio_server());
        return Ok(());
    }
    // `receipt verify [PATH]` is dispatched here rather than through the
    // framework: the affidavit dep re-registers its own `receipt verify
    // --receipt <RECEIPT>` over any override on every registry init (see
    // nouns::config::receipt_verify_cli). Everything else routes normally.
    let argv: Vec<String> = std::env::args().collect();
    if argv.len() >= 3 && argv[1] == "receipt" && argv[2] == "verify" {
        let path = argv
            .get(3)
            .map(|s| s.as_str())
            .filter(|s| !s.starts_with('-'));
        nouns::config::receipt_verify_cli(path);
        return Ok(());
    }
    clap_noun_verb::run()
}
